WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, attributes['utm_source'] AS utm_source, attributes['gift'] AS gift, FORALL(items, i -> i.qty <= 5) AS all_small_qty FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'VIP')) SELECT id, customer_id, created_at, utm_source, gift, all_small_qty, LAST_VALUE(utm_source, TRUE) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_utm_source FROM unpacked
